    ROSE("rose"), OCEAN("ocean"), SAGE("sage"), LAVENDER("lavender"), AMBER("amber"), GRAPHITE("graphite");

    companion object {
        fun fromKey(key: String?): PaperTheme = values().firstOrNull { it.key == key } ?: ROSE
